def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    n = sum(1 for v in g[0] if v == 3)
    if n == 0:
        n = sum(1 for row in g if row and row[0] == 3)
    step = n + 1
    red_rows = [r for r in range(h) if all(v == 3 for v in g[r])]
    red_cols = [c for c in range(w) if all(g[r][c] == 3 for r in range(h))]
    if red_rows:
        band = red_rows
        ri = band[0] // step
        starts_r = list(range(0, h - n + 1, step))
        starts_c = list(range(0, w - n + 1, step))
        for rix, r0 in enumerate(starts_r):
            if r0 in band:
                continue
            for cix, c0 in enumerate(starts_c):
                if rix >= n or cix >= n:
                    continue
                if g[r0][c0] == 0:
                    continue
                rr, cc = r0 + rix, c0 + cix
                if rr < r0+n and cc < c0+n and g[rr][cc] == 2:
                    g[rr][cc] = 8
        # Fill the red tile row wherever the corresponding motif pixel is occupied.
        target_index = ri
        for cix, c0 in enumerate(starts_c):
            if cix >= n or target_index >= n:
                continue
            sources = [r0 for r0 in starts_r if r0 not in band and g[r0][c0] != 0]
            if not sources:
                continue
            src = min(sources, key=lambda r0: abs(r0 - band[0]))
            tile = [g[src+i][c0:c0+n] for i in range(n)]
            if tile[target_index][cix] != 2:
                continue
            for i in range(n):
                for j in range(n):
                    g[band[0]+i][c0+j] = tile[i][j]
            g[band[0]+target_index][c0+cix] = 8
        for r in band:
            for c in range(w):
                if g[r][c] == 3: g[r][c] = 0
    elif red_cols:
        band = red_cols
        ci = band[0] // step
        starts_r = list(range(0, h - n + 1, step))
        starts_c = list(range(0, w - n + 1, step))
        for rix, r0 in enumerate(starts_r):
            for cix, c0 in enumerate(starts_c):
                if c0 in band or rix >= n or cix >= n:
                    continue
                if g[r0][c0] == 0:
                    continue
                rr, cc = r0 + rix, c0 + cix
                if rr < r0+n and cc < c0+n and g[rr][cc] == 2:
                    g[rr][cc] = 8
        target_index = ci
        for rix, r0 in enumerate(starts_r):
            if rix >= n or target_index >= n:
                continue
            sources = [c0 for c0 in starts_c if c0 not in band and g[r0][c0] != 0]
            if not sources:
                continue
            src = min(sources, key=lambda c0: abs(c0 - band[0]))
            tile = [g[r0+i][src:src+n] for i in range(n)]
            if tile[rix][target_index] != 2:
                continue
            for i in range(n):
                for j in range(n):
                    g[r0+i][band[0]+j] = tile[i][j]
            g[r0+rix][band[0]+target_index] = 8
        for r in range(h):
            for c in band:
                if g[r][c] == 3: g[r][c] = 0
    return g
